16	import { loadDailyLooks, saveDailyLooks } from "@/lib/outfits/daily";
17	import { reassembleLooks } from "@/lib/outfits/reassemble";
18	import {
19	  assertCanGenerate,
20	  noteGeneration,
21	  QuotaExceededError,
22	  type GenerationRequest,
23	} from "@/lib/outfits/quota";
24	import { predictOccasion, defaultReason } from "@/lib/outfits/predict-occasion";
25	import { recordOverride } from "@/lib/outfits/overrides";
26	import {
27	  resolveLocation,
28	  roundCoord,
29	  locationColumns,
30	  invalidatesDrop,
31	  LocationInputSchema,
32	  type LocationSource,
33	} from "@/lib/weather/location";
34	import type {
35	  GenerateResult,
36	  Look,
37	  LookDraft,
38	  LookPiece,
39	  UiOccasion,
40	  WeatherPayload,
41	} from "@/lib/generator/types";
42	
43	export async function generate(input: {
44	  occasion: UiOccasion;
45	  formality: number | null;
46	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
47	  lean: string[];
48	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
49	  regenerate?: boolean;
50	  city?: { lat: number; lon: number; label: string; source: LocationSource };
51	}): Promise<GenerateResult> {
52	  try {
53	    const supabase = await createClient();
54	    const {
55	      data: { user },
56	    } = await supabase.auth.getUser();
57	    if (!user) return { status: "error", message: "Not signed in" };
58	
59	    const { data: profile } = await supabase
60	      .from("profiles")
61	      .select(
62	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
63	      )
64	      .eq("id", user.id)
65	      .single();
66	    const { data: itemsRaw } = await supabase
67	      .from("items")
68	      .select("*")
69	      .eq("user_id", user.id)
70	      .eq("archived", false);
71	    const items = itemsRaw ?? [];
72	    const byId = new Map(items.map((i) => [i.id, i]));
73	    const pathFor = (id: string) => {
74	      const it = byId.get(id);
75	      return it ? displayPath(it) : undefined;
76	    };
77	
78	    const loc = resolveLocation({ input: input.city, profile });
79	
80	    const now = new Date();
81	    const f = await fetchForecast(loc.lat, loc.lon);
82	    const prefs = readPreferences(profile?.preferences);
83	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
84	    const weather: WeatherPayload = {
85	      tempC: f.tempC,
86	      feelsLikeC: f.feelsLikeC,
87	      condition: f.condition,
88	      cityLabel: loc.label,
89	      timezone: f.timezone,
90	      locationOrigin: loc.origin,
91	      laterSentence: advice.sentence,
92	      adviceClause: advice.adviceClause,
93	      laterLabel: "Later",
94	      hourly: f.hourly,
95	      tempUnit: prefs.tempUnit,
96	    };
97	
98	    const today = localDateFor(now, f.timezone);
99	
100	    // The daily drop (Decision 5): today's looks are generated once and then
101	    // read back. Only an explicit regenerate spends an AI call on a day the
102	    // stylist has already answered.
103	    //
104	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
105	    // on a regenerate it is the recency signal — the pieces the user just
106	    // rejected, which ranking will sink without ever filtering them out.
107	    const stored = await loadDailyLooks(user.id, input.occasion, today);
108	
109	    /**
110	     * Today's looks were composed for wherever the user was when they were
111	     * generated. Moving invalidates them: Decision 5 caches the drop, but
112	     * caching does not make a 26°C Manila outfit correct under a 12°C
113	     * Reykjavik sky.
114	     *
115	     * INTENT decides, not distance: a deliberate city pick always rebuilds,
116	     * however near, because the user asked and a screen that does not change
117	     * reads as broken. A silent GPS refresh only rebuilds past 25km, so a
118	     * commute does not cost a generation. See `invalidatesDrop`.
119	     *
120	     * Falling through here is deliberately how this is implemented: the block
121	     * below already records a fall-through as a `drop`, never a `regenerate`,
122	     * so the rebuild is free on every tier. The user changed where they are;
123	     * they did not ask for another look.
124	     *
125	     * The Settings path clears the stored rows outright in `setLocation`. This
126	     * covers the OTHER door — the Stylist's weather pill, which writes through
127	     * `saveLocation` AFTER this action has already run, and so cannot clear
128	     * anything without deleting the looks this very call just stored.
129	     */
130	    const movedAway = input.city
131	      ? invalidatesDrop(input.city, resolveLocation({ profile }))
132	      : false;
133	
134	    if (!input.regenerate && !movedAway && stored?.length) {
135	      const paths = Array.from(
136	        new Set(
137	          stored
138	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
139	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
140	            .map((it) => displayPath(it)),
141	        ),
142	      );
143	      const signed = await signItemImages(paths);
144	      const looks = reassembleLooks(stored, byId, signed, pathFor);
145	      // null = the closet changed under the stored set; fall through and
146	      // regenerate rather than showing an outfit with a hole in it.
147	      if (looks) return { status: "ok", weather, looks };
148	    }
149	
150	    // Only a deliberate regenerate carries the signal. A fall-through from a
151	    // stale stored set is the app fixing itself, not the user asking for
152	    // something else — penalising those pieces would be arbitrary.
153	    const recentlyShown = input.regenerate
154	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
155	      : [];
156	
157	    /**
158	     * A fall-through is a DROP, not a regenerate.
159	     *
160	     * Reaching here without `input.regenerate` means either the occasion has no
161	     * looks today, or the stored set no longer reassembles because the closet
162	     * changed under it. Both are the app answering for the first time or
163	     * repairing its own bookkeeping — not the user asking again — and neither
164	     * should be charged. Drops are free on every tier regardless, so the
165	     * distinction only matters for what the ledger records.
166	     */
167	    const gen: GenerationRequest = {
168	      kind: input.regenerate ? "regenerate" : "drop",
169	      occasion: input.occasion,
170	      today,
171	    };
172	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
173	    // in scope so the screen keeps its strip instead of collapsing, and being
174	    // limited is a STATE, not a failure — routing it through the error path
175	    // would render "Couldn't reach the stylist" for a working app.
176	    try {
177	      await assertCanGenerate(user.id, gen);
178	    } catch (e) {
179	      if (e instanceof QuotaExceededError) {
180	        return { status: "limited", weather, message: e.message };
181	      }
182	      throw e;
183	    }
184	
185	    const candItems: CandidateItem[] = items.map((i) => ({
186	      id: i.id,
187	      category: i.category,
188	      colors: i.colors ?? [],
189	      formality: i.formality,
190	      seasons: i.seasons ?? [],
191	      material: i.material,
192	    }));
193	    // Occasion gives the context; the user's onboarding dress codes narrow it;
194	    // an explicit Refine formality overrides both.
195	    const band = applyFormalityOverride(
196	      personalBand(input.occasion, profile),
197	      input.formality,
198	    );
199	    const candidateArgs = {
200	      band,
201	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
202	      season: currentSeason(now),
203	      excludeItemIds: [],
204	      maxAccessories: 1,
205	      rainGuard: prefs.rainGuard,
206	    };
207	    const combos = buildCandidates(candItems, candidateArgs);
208	    if (combos.length === 0) {
209	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
210	    }
211	
212	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
213	    // The Refine colour pick lands here, in ranking — not in candidate building.
214	    // It reorders the shortlist toward the requested families and is dropped
215	    // silently when the closet cannot honour it.
216	    //
217	    // Rank everything, then spread the shortlist across the wardrobe before the
218	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
219	    // top harmonises with everything, so it occupies most of the list, and "the
220	    // best 3" of a clustered list is three versions of one outfit. Diversifying
221	    // the INPUT makes the model's three distinct by construction.
222	    // Season rides along as a ranking preference — in-season combos float to the
223	    // top of the shortlist the re-ranker sees, but an off-season one is still
224	    // offered rather than the screen going empty.
225	    const ranked = rankTopN(
226	      combos,
227	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
228	      combos.length,
229	    );
230	    const top = diversify(ranked, 20);
231	
232	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
233	    // in place, so it has to survive in what we hand back to the screen too —
234	    // otherwise the day's set silently loses it until the next page load. It
235	    // also still COUNTS toward the day's three, so the stylist is asked for
236	    // fewer fresh looks rather than the set growing a fourth tab.
237	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
238	
239	    const { picks } = await rerank({
240	      want: MAX_PICKS - pinnedStored.length,
241	      combos: top.map((t) =>
242	        t.items.map((ci) => {
243	          const it = byId.get(ci.id)!;
244	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
245	        }),
246	      ),
247	      aesthetic,
248	      occasion: input.occasion,
249	      weatherLabel: f.condition,
250	      tempC: f.tempC,
251	    });
252	
253	    const paths = Array.from(
254	      new Set([
255	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
256	        ...pinnedStored.flatMap((s) =>
257	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
258	        ),
259	      ]),
260	    );
261	    const signed = await signItemImages(paths);
262	
263	    // `rerank` already dropped picks that repeat a combo or point outside the
264	    // shortlist, so every index here resolves. It previously fell back to
265	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
266	    // of the first look rather than into one fewer look.
267	    const drafts: LookDraft[] = picks.map((p) => {
268	      const combo = top[p.combo_index].items;
269	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
270	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
271	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
272	        itemId: d.id,
273	        category: d.category,
274	        subcategory: d.subcategory ?? null,
275	        brand: d.brand ?? null,
276	        name: d.name ?? null,
277	        colors: d.colors ?? [],
278	        cutoutUrl: signed.get(displayPath(d)) ?? "",
279	        slot: slots[idx],
280	      }));
281	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
282	    });
283	
284	    // Fire-and-forget would be simpler, but a failed write means the user pays
285	    // for another AI call on their next tap — worth awaiting. The insert also
286	    // hands back the row ids, which are the detail screen's address.
287	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
288	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
289	
290	    // Recorded only now — after the model answered and the write succeeded. A
291	    // generation that failed cost the user nothing, so metering it would be
292	    // charging them for our error.
293	    await noteGeneration(user.id, gen);
294	
295	    // Pinned looks keep their place at the front — they hold the lower
296	    // look_index values, which is the order the next load will read them back in.
297	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
298	
299	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
300	  } catch (e) {
301	    console.error("[generate] failed:", e);
302	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
303	  }
304	}
305	
306	/**
307	 * The single write path for a user's location. `generate` stays read-only.
308	 * Called by the client after a successful generate for a location the user
309	 * actually supplied (geolocation or city search) — never for the profile or
310	 * default fallback, where there is nothing new to write.
311	 */
312	export async function saveLocation(input: unknown): Promise<void> {
313	  const d = LocationInputSchema.parse(input);
314	
315	  const supabase = await createClient();
316	  const {
317	    data: { user },
318	  } = await supabase.auth.getUser();
319	  if (!user) return;
320	
321	  await supabase
322	    .from("profiles")
323	    .update(locationColumns(d, new Date().toISOString()))
324	    .eq("id", user.id);
325	}
326	
327	/**
328	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
329	 * AI and NO weather — so the client can pick the right occasion before the first
330	 * generate without adding latency.
331	 */
332	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
333	  const supabase = await createClient();
334	  const {
335	    data: { user },
336	  } = await supabase.auth.getUser();
337	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
338	
339	  const { data: profile } = await supabase
340	    .from("profiles")
341	    .select("occasions, location_timezone")
342	    .eq("id", user.id)
343	    .single();
344	
345	  const tz = profile?.location_timezone ?? "UTC";
346	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
347	  return { occasion, reason: defaultReason(occasion) };
348	}
349	
350	/**
351	 * Record that the user chose an occasion other than the predicted default.
352	 * Fire-and-forget: the caller does not await the outcome, and a failure here
353	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
354	 * not logged as an override.
355	 */
356	export async function logOccasionOverride(input: {
357	  predicted: UiOccasion;
358	  chosen: UiOccasion;
359	}): Promise<void> {
360	  if (input.chosen === input.predicted) return;
361	
362	  const supabase = await createClient();
363	  const {
364	    data: { user },
365	  } = await supabase.auth.getUser();
366	  if (!user) return;
367	
368	  const { data: profile } = await supabase
369	    .from("profiles")
370	    .select("location_timezone")
371	    .eq("id", user.id)
372	    .single();
373	
374	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
375	  await recordOverride(user.id, today, input.predicted, input.chosen);
376	}
