"use server";

import { createClient } from "@/lib/supabase/server";
import { signItemImages, displayPath } from "@/lib/storage/signed";
import { fetchForecast } from "@/lib/weather/open-meteo";
import { laterAdvice } from "@/lib/weather/advice";
import { readPreferences } from "@/lib/profile/preferences";
import { personalBand, applyFormalityOverride } from "@/lib/generator/rules";
import { buildCandidates, missingCategory, type CandidateItem } from "@/lib/generator/candidates";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";
import { currentSeason } from "@/lib/generator/season";
import { rerank, MAX_PICKS } from "@/lib/generator/rerank";
import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
import { localDateFor } from "@/lib/outfits/local-date";
import { loadDailyLooks, saveDailyLooks } from "@/lib/outfits/daily";
import { reassembleLooks } from "@/lib/outfits/reassemble";
import {
  assertCanGenerate,
  noteGeneration,
  QuotaExceededError,
  type GenerationRequest,
} from "@/lib/outfits/quota";
import { predictOccasion, defaultReason } from "@/lib/outfits/predict-occasion";
import { recordOverride } from "@/lib/outfits/overrides";
import {
  resolveLocation,
  roundCoord,
  locationColumns,
  invalidatesDrop,
  LocationInputSchema,
  type LocationSource,
} from "@/lib/weather/location";
import type {
  GenerateResult,
  Look,
  LookDraft,
  LookPiece,
  UiOccasion,
  WeatherPayload,
} from "@/lib/generator/types";

export async function generate(input: {
  occasion: UiOccasion;
  formality: number | null;
  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
  lean: string[];
  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
  regenerate?: boolean;
  city?: { lat: number; lon: number; label: string; source: LocationSource };
}): Promise<GenerateResult> {
  try {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return { status: "error", message: "Not signed in" };

    const { data: profile } = await supabase
      .from("profiles")
      .select(
        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
      )
      .eq("id", user.id)
      .single();
    const { data: itemsRaw } = await supabase
      .from("items")
      .select("*")
      .eq("user_id", user.id)
      .eq("archived", false);
    const items = itemsRaw ?? [];
    const byId = new Map(items.map((i) => [i.id, i]));
    const pathFor = (id: string) => {
      const it = byId.get(id);
      return it ? displayPath(it) : undefined;
    };

    const loc = resolveLocation({ input: input.city, profile });

    const now = new Date();
    const f = await fetchForecast(loc.lat, loc.lon);
    const prefs = readPreferences(profile?.preferences);
    const advice = laterAdvice(f.hourly, prefs.tempUnit);
    const weather: WeatherPayload = {
      tempC: f.tempC,
      feelsLikeC: f.feelsLikeC,
      condition: f.condition,
      cityLabel: loc.label,
      timezone: f.timezone,
      locationOrigin: loc.origin,
      laterSentence: advice.sentence,
      adviceClause: advice.adviceClause,
      laterLabel: "Later",
      hourly: f.hourly,
      tempUnit: prefs.tempUnit,
    };

    const today = localDateFor(now, f.timezone);

    // The daily drop (Decision 5): today's looks are generated once and then
    // read back. Only an explicit regenerate spends an AI call on a day the
    // stylist has already answered.
    //
    // The stored set is read on BOTH paths. On a normal load it IS the answer;
    // on a regenerate it is the recency signal — the pieces the user just
    // rejected, which ranking will sink without ever filtering them out.
    const stored = await loadDailyLooks(user.id, input.occasion, today);

    /**
     * Today's looks were composed for wherever the user was when they were
     * generated. Moving invalidates them: Decision 5 caches the drop, but
     * caching does not make a 26°C Manila outfit correct under a 12°C
     * Reykjavik sky.
     *
     * INTENT decides, not distance: a deliberate city pick always rebuilds,
     * however near, because the user asked and a screen that does not change
     * reads as broken. A silent GPS refresh only rebuilds past 25km, so a
     * commute does not cost a generation. See `invalidatesDrop`.
     *
     * Falling through here is deliberately how this is implemented: the block
     * below already records a fall-through as a `drop`, never a `regenerate`,
     * so the rebuild is free on every tier. The user changed where they are;
     * they did not ask for another look.
     *
     * The Settings path clears the stored rows outright in `setLocation`. This
     * covers the OTHER door — the Stylist's weather pill, which writes through
     * `saveLocation` AFTER this action has already run, and so cannot clear
     * anything without deleting the looks this very call just stored.
     */
    const movedAway = input.city
      ? invalidatesDrop(input.city, resolveLocation({ profile }))
      : false;

    if (!input.regenerate && !movedAway && stored?.length) {
      const paths = Array.from(
        new Set(
          stored
            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
            .filter((it): it is NonNullable<typeof it> => Boolean(it))
            .map((it) => displayPath(it)),
        ),
      );
      const signed = await signItemImages(paths);
      const looks = reassembleLooks(stored, byId, signed, pathFor);
      // null = the closet changed under the stored set; fall through and
      // regenerate rather than showing an outfit with a hole in it.
      if (looks) return { status: "ok", weather, looks };
    }

    // Only a deliberate regenerate carries the signal. A fall-through from a
    // stale stored set is the app fixing itself, not the user asking for
    // something else — penalising those pieces would be arbitrary.
    const recentlyShown = input.regenerate
      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
      : [];

    /**
     * A fall-through is a DROP, not a regenerate.
     *
     * Reaching here without `input.regenerate` means either the occasion has no
     * looks today, or the stored set no longer reassembles because the closet
     * changed under it. Both are the app answering for the first time or
     * repairing its own bookkeeping — not the user asking again — and neither
     * should be charged. Drops are free on every tier regardless, so the
     * distinction only matters for what the ledger records.
     */
    const gen: GenerationRequest = {
      kind: input.regenerate ? "regenerate" : "drop",
      occasion: input.occasion,
      today,
    };
    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
    // in scope so the screen keeps its strip instead of collapsing, and being
    // limited is a STATE, not a failure — routing it through the error path
    // would render "Couldn't reach the stylist" for a working app.
    try {
      await assertCanGenerate(user.id, gen);
    } catch (e) {
      if (e instanceof QuotaExceededError) {
        return { status: "limited", weather, message: e.message };
      }
      throw e;
    }

    const candItems: CandidateItem[] = items.map((i) => ({
      id: i.id,
      category: i.category,
      colors: i.colors ?? [],
      formality: i.formality,
      seasons: i.seasons ?? [],
      material: i.material,
    }));
    // Occasion gives the context; the user's onboarding dress codes narrow it;
    // an explicit Refine formality overrides both.
    const band = applyFormalityOverride(
      personalBand(input.occasion, profile),
      input.formality,
    );
    const candidateArgs = {
      band,
      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
      season: currentSeason(now),
      excludeItemIds: [],
      maxAccessories: 1,
      rainGuard: prefs.rainGuard,
    };
    const combos = buildCandidates(candItems, candidateArgs);
    if (combos.length === 0) {
      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
    }

    const aesthetic = profile?.archetype ? [profile.archetype] : [];
    // The Refine colour pick lands here, in ranking — not in candidate building.
    // It reorders the shortlist toward the requested families and is dropped
    // silently when the closet cannot honour it.
    //
    // Rank everything, then spread the shortlist across the wardrobe before the
    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
    // top harmonises with everything, so it occupies most of the list, and "the
    // best 3" of a clustered list is three versions of one outfit. Diversifying
    // the INPUT makes the model's three distinct by construction.
    // Season rides along as a ranking preference — in-season combos float to the
    // top of the shortlist the re-ranker sees, but an off-season one is still
    // offered rather than the screen going empty.
    const ranked = rankTopN(
      combos,
      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
      combos.length,
    );
    const top = diversify(ranked, 20);

    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
    // in place, so it has to survive in what we hand back to the screen too —
    // otherwise the day's set silently loses it until the next page load. It
    // also still COUNTS toward the day's three, so the stylist is asked for
    // fewer fresh looks rather than the set growing a fourth tab.
    const pinnedStored = (stored ?? []).filter((s) => s.worn);

    const { picks } = await rerank({
      want: MAX_PICKS - pinnedStored.length,
      combos: top.map((t) =>
        t.items.map((ci) => {
          const it = byId.get(ci.id)!;
          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
        }),
      ),
      aesthetic,
      occasion: input.occasion,
      weatherLabel: f.condition,
      tempC: f.tempC,
    });

    const paths = Array.from(
      new Set([
        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
        ...pinnedStored.flatMap((s) =>
          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
        ),
      ]),
    );
    const signed = await signItemImages(paths);

    // `rerank` already dropped picks that repeat a combo or point outside the
    // shortlist, so every index here resolves. It previously fell back to
    // `top[0]` for an unknown index, which turned a bad index into a duplicate
    // of the first look rather than into one fewer look.
    const drafts: LookDraft[] = picks.map((p) => {
      const combo = top[p.combo_index].items;
      const dbItems = combo.map((ci) => byId.get(ci.id)!);
      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
        itemId: d.id,
        category: d.category,
        subcategory: d.subcategory ?? null,
        brand: d.brand ?? null,
        name: d.name ?? null,
        colors: d.colors ?? [],
        cutoutUrl: signed.get(displayPath(d)) ?? "",
        slot: slots[idx],
      }));
      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
    });

    // Fire-and-forget would be simpler, but a failed write means the user pays
    // for another AI call on their next tap — worth awaiting. The insert also
    // hands back the row ids, which are the detail screen's address.
    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));

    // Recorded only now — after the model answered and the write succeeded. A
    // generation that failed cost the user nothing, so metering it would be
    // charging them for our error.
    await noteGeneration(user.id, gen);

    // Pinned looks keep their place at the front — they hold the lower
    // look_index values, which is the order the next load will read them back in.
    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];

    return { status: "ok", weather, looks: [...pinned, ...fresh] };
  } catch (e) {
    console.error("[generate] failed:", e);
    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
  }
}

/**
 * The single write path for a user's location. `generate` stays read-only.
 * Called by the client after a successful generate for a location the user
 * actually supplied (geolocation or city search) — never for the profile or
 * default fallback, where there is nothing new to write.
 */
export async function saveLocation(input: unknown): Promise<void> {
  const d = LocationInputSchema.parse(input);

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return;

  await supabase
    .from("profiles")
    .update(locationColumns(d, new Date().toISOString()))
    .eq("id", user.id);
}

/**
 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
 * AI and NO weather — so the client can pick the right occasion before the first
 * generate without adding latency.
 */
export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };

  const { data: profile } = await supabase
    .from("profiles")
    .select("occasions, location_timezone")
    .eq("id", user.id)
    .single();

  const tz = profile?.location_timezone ?? "UTC";
  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
  return { occasion, reason: defaultReason(occasion) };
}

/**
 * Record that the user chose an occasion other than the predicted default.
 * Fire-and-forget: the caller does not await the outcome, and a failure here
 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
 * not logged as an override.
 */
export async function logOccasionOverride(input: {
  predicted: UiOccasion;
  chosen: UiOccasion;
}): Promise<void> {
  if (input.chosen === input.predicted) return;

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return;

  const { data: profile } = await supabase
    .from("profiles")
    .select("location_timezone")
    .eq("id", user.id)
    .single();

  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
  await recordOverride(user.id, today, input.predicted, input.chosen);
}

