18	
19	test("client-chosen location wins over everything, carrying its source as the origin", () => {
20	  const r = resolveLocation({
21	    input: { lat: 51.5, lon: -0.1, label: "London", source: "city" },
22	    profile: { location_lat: 48.14, location_lon: 11.58, location_label: "Munich" },
23	  });
24	  expect(r).toEqual({ lat: 51.5, lon: -0.1, label: "London", origin: "city" });
25	});
