48	  const r = resolveLocation({
49	    profile: { location_lat: 48.14, location_lon: 11.58, location_label: null },
50	  });
51	  expect(r.label).toBe("Current location");
52	});
53	
54	test("a stored city is reported as origin 'city' — GPS must not silently override it", () => {
55	  const r = resolveLocation({
56	    profile: {
57	      location_lat: 35.69, location_lon: 139.69,
58	      location_label: "Tokyo", location_source: "city",
59	    },
60	  });
61	  expect(r.origin).toBe("city");
62	  expect(r.label).toBe("Tokyo");
63	});
64	
65	test("a stored geo fix is reported as origin 'geo' — safe to silently refresh", () => {
66	  const r = resolveLocation({
67	    profile: {
68	      location_lat: 47.24, location_lon: 8.92,
69	      location_label: "Current location", location_source: "geo",
70	    },
71	  });
72	  expect(r.origin).toBe("geo");
73	});
74	
75	test("a legacy row with coords but no source is plain 'profile'", () => {
76	  const r = resolveLocation({
77	    profile: { location_lat: 47.24, location_lon: 8.92, location_label: null },
78	  });
79	  expect(r.origin).toBe("profile");
80	});
81	
82	test("LocationInputSchema accepts a well-formed fix", () => {
83	  const ok = LocationInputSchema.parse({
84	    lat: 52.52, lon: 13.41, label: "Berlin", source: "city", timezone: "Europe/Berlin",
85	  });
86	  expect(ok.label).toBe("Berlin");
87	});
88	
89	test("LocationInputSchema rejects out-of-range coordinates", () => {
90	  const bad = { lon: 13.41, label: "Nowhere", source: "geo", timezone: "Europe/Berlin" };
